mapper.select:
SELECT attachment.id, attachment.content_type, attachment.data FROM chat_attachment attachment
JOIN chat_message message ON message.id = attachment.message_id
WHERE message.group_id = #{groupId} AND attachment.id = #{attachmentId}

mapper.insert:
WITH reserved AS (
    UPDATE chat_file_storage_quota
    SET reserved_bytes = reserved_bytes + #{byteSize}
    WHERE id = 1 AND used_bytes + reserved_bytes + #{byteSize} <= #{maxStorageSize}
    RETURNING id
)
INSERT INTO chat_file_upload_reservation (id, group_id, byte_size, created_at)
SELECT #{uploadId}, #{groupId}, #{byteSize}, #{createdAt} FROM reserved
